5	// Design space 600 x 1000 units (soles at y = 975); the canvas transform scales it.
6	export const INK = "#241726";
7	export const SKIN = "#ffe2c2";
8	const WHITE = "#ffffff";
9	const MOUTH = "#5a1e28";
10	const TONGUE = "#e86e78";
11	type C3 = [number, number, number];
12	const SH_SKIN: C3 = [0.96, 0.86, 0.84]; // measured shadow/lit ratio on skin heads
13	const SH_CLOTH: C3 = [0.64, 0.66, 0.74]; // torsos: lit side -> far side ~0.65
14	const SH_FELT: C3 = [0.62, 0.62, 0.7];
