16	export type Build = "adult" | "stout" | "kid";
17	export type Outfit = {
18	  jacket: string; pants: string; boots: string; hat?: string | null; belt?: string | null; buttons?: string; rifle?: boolean;
19	  sash?: string; sword?: boolean; moustache?: string; skin?: string; head?: number; cap?: string; hair?: string; dress?: string;
20	  build?: Build;
21	};
22	type P2 = [number, number];
23	
24	const rad = (d: number) => (d * Math.PI) / 180;
25	const clamp = (x: number, a: number, b: number) => Math.max(a, Math.min(b, x));
26	export const mul = (c: string, m: C3) => {
27	  const n = parseInt(c.slice(1), 16);
28	  const ch = (v: number, k: number) => Math.min(255, Math.round(v * k)).toString(16).padStart(2, "0");
29	  return `#${ch((n >> 16) & 255, m[0])}${ch((n >> 8) & 255, m[1])}${ch(n & 255, m[2])}`;
30	};
31	export const shade = (c: string, k: number) => mul(c, [k, k, k]);
32	export const mix = (a: string, b: string, t: number) => {
33	  const A = parseInt(a.slice(1), 16), B = parseInt(b.slice(1), 16);
34	  const ch = (s: number) => Math.round(((A >> s) & 255) * (1 - t) + ((B >> s) & 255) * t).toString(16).padStart(2, "0");
35	  return `#${ch(16)}${ch(8)}${ch(0)}`;
36	};
37	/** deterministic per-character random in [0, 1) */
38	const rnd = (seed: number, k: number) => { const x = Math.sin(seed * 127.1 + k * 311.7) * 43758.5453; return x - Math.floor(x); };
39	const rotPts = (pts: P2[], a: number, cx: number, cy: number): P2[] =>
40	  pts.map(([x, y]) => [cx + (x - cx) * Math.cos(a) - (y - cy) * Math.sin(a), cy + (x - cx) * Math.sin(a) + (y - cy) * Math.cos(a)]);
41	const rotAbout = (q: P2, a: number, c: P2): P2 => rotPts([q], a, c[0], c[1])[0];
42	const lerp2 = (a: P2, b: P2, t: number): P2 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
43	/** smooth curve from a through (near) k to b, as a polyline */
44	const curve = (a: P2, k: P2, b: P2, n = 10): P2[] => {
45	  const c: P2 = [2 * k[0] - (a[0] + b[0]) / 2, 2 * k[1] - (a[1] + b[1]) / 2], out: P2[] = [];
46	  for (let i = 0; i <= n; i++) {
47	    const t = i / n, s = 1 - t;
48	    out.push([s * s * a[0] + 2 * s * t * c[0] + t * t * b[0], s * s * a[1] + 2 * s * t * c[1] + t * t * b[1]]);
49	  }
50	  return out;
51	};
