72	export class Pen {
73	  g: CanvasRenderingContext2D;
74	  ol = 12;
75	  /** [angle, cx, cy] rotation about (cx, cy), optional post-translation [.., dx, dy] */
76	  rot: number[] | null = null;
77	  constructor(g: CanvasRenderingContext2D) { this.g = g; }
78	  P(x: number, y: number): P2 {
79	    if (!this.rot) return [x, y];
80	    const r = this.rot, a = r[0], cx = r[1], cy = r[2], dx = r.length > 3 ? r[3] : 0, dy = r.length > 4 ? r[4] : 0, c = Math.cos(a), s = Math.sin(a);
81	    return [cx + (x - cx) * c - (y - cy) * s + dx, cy + (x - cx) * s + (y - cy) * c + dy];
82	  }
83	  path(pts: P2[], close: boolean) {
84	    const g = this.g;
85	    g.beginPath();
86	    pts.forEach((p, i) => { const [x, y] = this.P(p[0], p[1]); if (i) g.lineTo(x, y); else g.moveTo(x, y); });
87	    if (close) g.closePath();
88	  }
89	  /** filled shape with an ink outline; fill=null draws the outline only */
90	  poly(pts: P2[], fill: string | null, ol?: number) {
91	    const g = this.g, w = ol ?? this.ol;
92	    this.path(pts, true);
93	    if (fill) { g.fillStyle = fill; g.fill(); }
94	    if (w) { g.lineWidth = w; g.strokeStyle = INK; g.lineJoin = "round"; g.stroke(); }
95	  }
96	  ell(cx: number, cy: number, rx: number, ry: number, fill: string | null, ol?: number, a0 = 0, a1 = 360, rot = 0) {
97	    this.poly(ellPts(cx, cy, rx, ry, a0, a1, rot), fill, ol);
98	  }
99	  /** thick round-capped limb with an ink rim (effects, rope) */
100	  line(pts: P2[], fill: string, w: number, ink = true) {
101	    const g = this.g;
102	    g.lineCap = "round"; g.lineJoin = "round";
103	    if (ink) { this.path(pts, false); g.strokeStyle = INK; g.lineWidth = w + 2 * this.ol * 0.9; g.stroke(); }
104	    this.path(pts, false); g.strokeStyle = fill; g.lineWidth = w; g.stroke();
105	  }
106	  stroke(pts: P2[], w: number, fill = INK) {
107	    const g = this.g;
108	    g.lineCap = "round"; g.lineJoin = "round";
109	    this.path(pts, false); g.strokeStyle = fill; g.lineWidth = w; g.stroke();
110	  }
111	  arc(cx: number, cy: number, rx: number, ry: number, a0: number, a1: number, w: number, fill = INK) {
112	    const pts: P2[] = [];
113	    for (let i = 0; i <= 24; i++) pts.push([cx + rx * Math.cos(rad(a0 + ((a1 - a0) * i) / 24)), cy + ry * Math.sin(rad(a0 + ((a1 - a0) * i) / 24))]);
114	    this.stroke(pts, w, fill);
115	  }
116	  dot(cx: number, cy: number, r: number, fill = INK) {
117	    const [x, y] = this.P(cx, cy);
118	    this.g.beginPath(); this.g.arc(x, y, r, 0, Math.PI * 2); this.g.fillStyle = fill; this.g.fill();
119	  }
120	  /** draw with a closed shape as clip */
121	  clip(pts: P2[], fn: () => void) { const g = this.g; g.save(); this.path(pts, true); g.clip(); fn(); g.restore(); }
122	  /** flat fill + soft crescent on the side away from the light (light = canvas angle the light comes FROM).
123	   *  Radial ramp centred `shift` R toward the light: flat out to ~0.6 R on the far side, full shadow by ~0.8 R. */
124	  shadedFill(pts: P2[], base: string, shadow: string, light: number, R: number, shift = 0.45, r0 = 1.05, r1 = 1.25) {
125	    const g = this.g, n = pts.length;
126	    let cx = 0, cy = 0;
127	    for (const [x, y] of pts) { cx += x / n; cy += y / n; }
128	    const [gx, gy] = this.P(cx + Math.cos(light) * shift * R, cy + Math.sin(light) * shift * R);
129	    const gr = g.createRadialGradient(gx, gy, 0, gx, gy, r1 * R);
130	    gr.addColorStop(0, base); gr.addColorStop(r0 / r1, base); gr.addColorStop(1, shadow);
131	    this.path(pts, true); g.fillStyle = gr; g.fill();
132	  }
133	  /** broad gradient across a shape along the light: lit edge = base, far edge = shadow (torsos, coats) */
134	  gradFill(pts: P2[], base: string, shadow: string, light: number, flat = 0.22) {
135	    const g = this.g, dx = Math.cos(light), dy = Math.sin(light), n = pts.length;
136	    let cx = 0, cy = 0, lo = Infinity, hi = -Infinity;
137	    for (const [x, y] of pts) { cx += x / n; cy += y / n; const d = x * dx + y * dy; lo = Math.min(lo, d); hi = Math.max(hi, d); }
138	    const dc = cx * dx + cy * dy;
139	    const [ax, ay] = this.P(cx + dx * (hi - dc), cy + dy * (hi - dc)), [bx, by] = this.P(cx + dx * (lo - dc), cy + dy * (lo - dc));
140	    const gr = g.createLinearGradient(ax, ay, bx, by);
141	    gr.addColorStop(0, base); gr.addColorStop(flat, base); gr.addColorStop(1, shadow);
142	    this.path(pts, true); g.fillStyle = gr; g.fill();
143	  }
144	  /** thick-thin ink ring: w(θ) = w0 (1 + k cos(θ − thick)), θ from the contour centroid (canvas angles) */
145	  inkRing(pts: P2[], w0: number, thick: number, k = 0.45, col = INK) {
146	    const n = pts.length;
147	    let cx = 0, cy = 0;
148	    for (const [x, y] of pts) { cx += x / n; cy += y / n; }
149	    const out: P2[] = [], inn: P2[] = [];
150	    pts.forEach((q, i) => {
151	      const a = pts[(i + n - 1) % n], b = pts[(i + 1) % n];
152	      let nx = b[1] - a[1], ny = a[0] - b[0]; // outward normal for clockwise-on-screen contours
153	      const l = Math.hypot(nx, ny) || 1; nx /= l; ny /= l;
154	      const h = 0.5 * w0 * (1 + k * Math.cos(Math.atan2(q[1] - cy, q[0] - cx) - thick));
155	      out.push([q[0] + nx * h, q[1] + ny * h]); inn.push([q[0] - nx * h, q[1] - ny * h]);
156	    });
157	    const g = this.g;
158	    const trace = (r: P2[]) => { r.forEach(([x0, y0], i) => { const [x, y] = this.P(x0, y0); if (i) g.lineTo(x, y); else g.moveTo(x, y); }); g.closePath(); };
159	    g.beginPath(); trace(out); trace(inn.reverse());
160	    g.fillStyle = col; g.fill("evenodd");
161	  }
162	  /** flat strap with a thin ink rim (cross belts, sash, rifle, handles) */
163	  band(pts: P2[], fill: string, w: number, rim: number, cap: CanvasLineCap = "butt") {
164	    const g = this.g; g.lineCap = cap; g.lineJoin = "round";
165	    this.path(pts, false); g.strokeStyle = INK; g.lineWidth = w + 2 * rim; g.stroke();
166	    this.path(pts, false); g.strokeStyle = fill; g.lineWidth = w; g.stroke();
167	    g.lineCap = "round";
168	  }
169	}
170	
171	const ellPts = (cx: number, cy: number, rx: number, ry: number, a0 = 0, a1 = 360, rot = 0, n = 48): P2[] => {
172	  const r = rad(rot), pts: P2[] = [];
173	  for (let i = 0; i <= n; i++) {
174	    const a = rad(a0 + ((a1 - a0) * i) / n), x = rx * Math.cos(a), y = ry * Math.sin(a);
175	    pts.push([cx + x * Math.cos(r) - y * Math.sin(r), cy + x * Math.sin(r) + y * Math.cos(r)]);
176	  }
177	  return pts;
178	};
179	
180	const rrect = (x0: number, y0: number, x1: number, y1: number, r: number, n = 8): P2[] => {
181	  const pts: P2[] = [];
182	  for (const [cx, cy, a] of [[x1 - r, y0 + r, -90], [x1 - r, y1 - r, 0], [x0 + r, y1 - r, 90], [x0 + r, y0 + r, 180]])
183	    for (let i = 0; i <= n; i++) pts.push([cx + r * Math.cos(rad(a + (90 * i) / n)), cy + r * Math.sin(rad(a + (90 * i) / n))]);
184	  return pts;
185	};
186	
187	/** tapered stroke, thick end at a: brows, moustache halves */
188	const taper = (p: Pen, a: P2, b: P2, wa: number, wb: number, col = INK) => {
189	  const dx = b[0] - a[0], dy = b[1] - a[1], l = Math.hypot(dx, dy) || 1, nx = -dy / l, ny = dx / l;
190	  p.poly([[a[0] + nx * wa / 2, a[1] + ny * wa / 2], [b[0] + nx * wb / 2, b[1] + ny * wb / 2],
191	    [b[0] - nx * wb / 2, b[1] - ny * wb / 2], [a[0] - nx * wa / 2, a[1] - ny * wa / 2]], col, 0);
192	  p.dot(a[0], a[1], wa / 2, col); p.dot(b[0], b[1], wb / 2, col);
193	};
194	
195	// ---------------- contours ----------------
196	export type Blob = { a: number; b: number; nTop: number; nBot: number; egg: number; asym: number; rot: number; noise: number; seed: number };
197	
198	/** superellipse "bean": separate crown / jaw exponents, egg taper (neg = narrower chin), one-side bulge, soft noise.
199	 *  Points run right -> down -> left -> up (clockwise on screen). */
200	export const blobPts = (cx: number, cy: number, B: Blob, n = 72): P2[] => {
201	  const ph = [rnd(B.seed, 11), rnd(B.seed, 12), rnd(B.seed, 13)].map((v) => v * Math.PI * 2);
202	  const pts: P2[] = [];
203	  for (let i = 0; i < n; i++) {
204	    const t = (i / n) * Math.PI * 2, c = Math.cos(t), s = Math.sin(t), e = 2 / (s < 0 ? B.nTop : B.nBot);
205	    let X = Math.sign(c) * Math.abs(c) ** e;
206	    const Y = Math.sign(s) * Math.abs(s) ** e;
207	    X *= (1 + B.egg * Y) * (1 + B.asym * Math.sign(X));
208	    const r = 1 + B.noise * (Math.cos(2 * t + ph[0]) + 0.7 * Math.cos(3 * t + ph[1]) + 0.5 * Math.cos(4 * t + ph[2]));
209	    const x = B.a * X * r, y = B.b * Y * r;
210	    pts.push([cx + x * Math.cos(B.rot) - y * Math.sin(B.rot), cy + x * Math.sin(B.rot) + y * Math.cos(B.rot)]);
211	  }
212	  return pts;
213	};
214	
215	/** measured head: H/W 0.94, slightly pointed crown (1.75), fuller jaw (2.3), chin taper -0.12, 8 % bulge to the facing side */
216	export const headBlob = (seed: number, a = 118, facing = 0): Blob => ({
217	  a, b: a * (0.94 + 0.08 * (rnd(seed, 1) - 0.5)),
218	  nTop: 1.75 + 0.3 * (rnd(seed, 2) - 0.5), nBot: 2.3 + 0.3 * (rnd(seed, 3) - 0.5),
219	  egg: -0.12 + 0.06 * (rnd(seed, 4) - 0.5),
220	  asym: (0.06 + 0.04 * rnd(seed, 5)) * (facing || (rnd(seed, 6) < 0.5 ? -1 : 1)),
221	  rot: rad(8 * (rnd(seed, 7) - 0.5)), noise: 0.008, seed,
222	});
223	
224	/** thickest outline direction: away from the light, pulled toward the ground (64 deg measured for upper-left light) */
225	export const thickAngle = (light: number) => Math.atan2(-Math.sin(light) + 0.8, -Math.cos(light));
226	const DEF_LIGHT = rad(-120);
227	
228	// ---------------- faces ----------------
229	export type Expr = "neutral" | "stern" | "grin" | "laugh" | "whistle" | "nervous" | "shock" | "relief" | "relief_open" | "dazed"
230	  | "pained" | "smile" | "smile_closed" | "lick";
231	type EyeK = "dot" | "small" | "lid" | "slit" | "happy" | "dash" | "squeeze" | "shock" | "shockHalf" | "spiral";
232	type MouthK = "dash" | "frown" | "smirk" | "smile" | "smileWide" | "grin" | "laugh" | "o" | "O" | "wave" | "teeth" | "lick";
233	/** eyes [back, front], brows [inner, outer] offsets in u (+ = down), mouth kind */
234	const FACE: Record<Expr, { eye: [EyeK, EyeK]; brow: [number, number]; mouth: MouthK }> = {
235	  neutral: { eye: ["lid", "lid"], brow: [0, -1], mouth: "dash" },
236	  stern: { eye: ["lid", "lid"], brow: [3, -2], mouth: "frown" },
237	  grin: { eye: ["happy", "happy"], brow: [-3, -3], mouth: "grin" },
238	  laugh: { eye: ["squeeze", "squeeze"], brow: [-4, -4], mouth: "laugh" },
239	  whistle: { eye: ["dash", "dash"], brow: [-2, -4], mouth: "o" },
240	  nervous: { eye: ["small", "small"], brow: [-3, 2], mouth: "wave" },
241	  shock: { eye: ["shock", "shock"], brow: [-7, -6], mouth: "O" },
242	  relief: { eye: ["happy", "happy"], brow: [-2, 1], mouth: "smileWide" },
243	  relief_open: { eye: ["happy", "happy"], brow: [-2, 1], mouth: "grin" },
244	  dazed: { eye: ["spiral", "spiral"], brow: [-3, 2], mouth: "wave" },
245	  pained: { eye: ["squeeze", "lid"], brow: [-3, 2], mouth: "teeth" },
246	  smile: { eye: ["dot", "dot"], brow: [0, -1], mouth: "smirk" },
247	  smile_closed: { eye: ["happy", "happy"], brow: [0, -1], mouth: "smile" },
248	  lick: { eye: ["dot", "dot"], brow: [0, -1], mouth: "lick" },
249	};
250	const halfLid = (k: EyeK): EyeK => (k === "dot" || k === "small" ? "lid" : k === "lid" ? "slit" : k === "shock" ? "shockHalf" : k);

420	    p.stroke([[cx - 14 * u, cy - 4 * u], [cx, cy + 2 * u], [cx + 14 * u, cy - 4 * u]], 2 * u, BONNET_BRIM);
421	  }
422	};
423	
424	// ---------------- bodies ----------------
425	export type Arms = [P2[], P2[]];
426	/** held prop; for the hammer the number is the strike 0 (raised) .. 1 (struck) */
427	export type Prop = null | "icecream" | "shako" | ["hammer", number];
428	
429	const BUILD: Record<Build, { a: number; torso: number; legs: number; tw: number }> = {
430	  adult: { a: 118, torso: 1.1, legs: 1.4, tw: 0.8 },
431	  stout: { a: 118, torso: 1.15, legs: 1.32, tw: 0.92 },
432	  kid: { a: 112, torso: 0.85, legs: 1.0, tw: 0.72 },
433	};
434	
435	export type FrontOpts = {
436	  phase?: number; expr?: Expr; mode?: "march" | "stroll" | "stand" | "sit" | "fall"; look?: number; blink?: boolean | number; lift?: number;
437	  prop?: Prop; tilt?: number; headTilt?: number; wave?: number;
438	  /** canvas angle the key light comes FROM (painted crescent + thick outline side) */
439	  light?: number; facing?: -1 | 0 | 1; seed?: number;
440	};
441	
442	const footStroke = (p: Pen, a: P2, b: P2, w: number, col: string) => {
443	  if (col !== INK) p.stroke([a, b], w + 3, INK);
444	  p.stroke([a, b], w, col);
445	};
446	
447	export const bodyFront = (p: Pen, o: Outfit, opts: FrontOpts) => {
448	  const { phase = 0, expr = "neutral", mode = "march", look = 0, blink = false, lift = 60, prop = null, tilt = 0, headTilt = 0, wave,
449	    light = DEF_LIGHT, facing = 0, seed = 1 } = opts;
450	  const Bd = BUILD[o.build ?? "adult"], skin = o.skin ?? SKIN, two = Math.PI * 2, lid = lidOf(blink);
451	  const H = headBlob(seed, Bd.a, facing), W = 2 * H.a, HH = 2 * H.b, u = W / 100;
452	  const tall = (1 + Bd.torso + Bd.legs) * HH, sole = 975;
453	  // body bob 5 % (march) / 3 % (stroll) of the height, lowest at contact (phase 0 and 0.5)
454	  const bob = mode === "march" ? 0.025 * tall * Math.cos(2 * two * phase) : mode === "stroll" ? 0.015 * tall * Math.cos(2 * two * phase) : 0;
455	  const torsoBot = mode === "sit" ? sole - 0.2 * HH : sole - Bd.legs * HH + bob;
456	  const chin = torsoBot - Bd.torso * HH, hc = chin - H.b, crown = hc - H.b, hipY = torsoBot - 0.12 * HH;
457	  const thick = thickAngle(light), ow = 5 * u;
458	  const legCol = mix(o.pants, INK, 0.55), armCol = mix(o.jacket, INK, 0.5), footCol = o.boots;
459	  const legW = 5.8 * u, footW = 7.5 * u;
460	  // ---- legs + feet (not rotated) ----
461	  p.rot = null;
462	  if (mode === "sit") {
463	    for (const side of [-1, 1]) {
464	      const h: P2 = [300 + side * 15 * u, hipY], k: P2 = [300 + side * 36 * u, hipY + 0.2 * HH], f: P2 = [300 + side * 44 * u, sole - 8 * u];
465	      p.stroke(curve(h, k, f), legW, legCol);
466	      footStroke(p, [f[0] - side * 2 * u, f[1]], [f[0] + side * 12 * u, f[1] - 5 * u], footW, footCol);
467	    }
468	  } else if (mode === "fall") {
469	    const legs: [P2, P2, P2][] = [
470	      [[300 - 15 * u, hipY], [300 - 46 * u, hipY + 0.5 * HH], [300 - 70 * u, hipY + 0.72 * HH]],
471	      [[300 + 15 * u, hipY], [300 + 50 * u, hipY + 0.45 * HH], [300 + 76 * u, hipY + 0.22 * HH]],
472	    ];
473	    legs.forEach(([h, k, f], i) => {
474	      p.stroke(curve(h, k, f), legW, legCol);
475	      footStroke(p, f, [f[0] + (i ? 14 : -14) * u, f[1] + (i ? -6 : 4) * u], footW, footCol);
476	    });
477	  } else if (o.dress) {
478	    for (const side of [-1, 1]) {
479	      const fx = 300 + side * 12 * u, fy = sole - 4 * u;
480	      p.stroke([[fx, sole - 0.4 * HH], [fx + side * u, fy]], legW, legCol);
481	      footStroke(p, [fx - side * 3 * u, fy], [fx + side * 12 * u, fy + u], footW, footCol);
482	    }
483	  } else {
484	    const L = mode === "march" ? lift * 1.25 : mode === "stroll" ? lift * 0.55 : 0;
485	    for (const [side, ph] of [[-1, 0], [1, 0.5]] as const) {
486	      const up = Math.max(0, Math.sin(two * (phase + ph))) * L;
487	      const hx = 300 + side * 15 * u, fx = 300 + side * 22 * u, fy = sole - 4 * u - up;
488	      const k: P2 = [(hx + fx) / 2 + side * (1.5 * u + up * 0.16), (hipY + fy) / 2 - up * 0.08];
489	      p.stroke(curve([hx, hipY], k, [fx, fy]), legW, legCol);
490	      footStroke(p, [fx - side * 3 * u, fy], [fx + side * 13 * u, fy + 0.5 * u], footW, footCol);
491	    }
492	  }
493	  // ---- upper body: rotates about the hips (tilt + a small weight-shift sway on every step) ----
494	  const sway = mode === "march" ? 1.6 * Math.sin(two * phase) : mode === "stroll" ? 1.0 * Math.sin(two * phase) : 0;
495	  const A = tilt + sway;
496	  p.rot = A ? [rad(A), 300, hipY] : null;
497	  const dress = !!o.dress && mode !== "sit" && mode !== "fall";
498	  const T: Blob = { a: ((Bd.tw / 2) * W) / 1.06, b: 0.5 * (torsoBot - (chin - 0.25 * HH)), nTop: 2.2, nBot: 2.6, egg: o.build === "stout" ? 0.17 : 0.12,
499	    asym: 0.04 * facing, rot: 0, noise: 0.006, seed: seed + 7 };
500	  const tcx = 300 + 3 * u * facing, tcy = torsoBot - T.b, tp = blobPts(tcx, tcy, T);
501	  const sh = (side: number): P2 => [tcx + side * 0.85 * T.a, chin + 0.12 * HH];
502	  const hang = (side: number, fwd: number): [P2, P2, P2] => {
503	    const S = sh(side), ex = tcx + side * (1.12 * T.a + 4 * u);
504	    const hx = ex + side * 3 * u - side * 6 * u * Math.max(0, fwd) + side * 4 * u * Math.max(0, -fwd);
505	    return [S, [ex, S[1] + 0.48 * HH], [hx, chin + 1.04 * HH - Math.abs(fwd) * 9 * u]];
506	  };
507	  const sw = mode === "march" || mode === "stroll" ? Math.sin(two * phase) : 0;
508	  // rifle at the order: butt by the right hip, held by the hanging right hand, muzzle past the crown
509	  const R0: P2 = [300 + 47 * u, torsoBot + 0.12 * HH], R1: P2 = [300 + 64 * u, crown - 0.32 * HH];
510	  const rifle = !!o.rifle && (mode === "march" || mode === "stand" || mode === "stroll");
511	  type Arm = { pts: [P2, P2, P2]; front: boolean };
512	  const arms: Arm[] = [];
513	  if (mode === "sit") for (const side of [-1, 1]) arms.push({ pts: [sh(side), [tcx + side * (1.1 * T.a + 6 * u), sh(side)[1] + 0.4 * HH], [tcx + side * (1.2 * T.a + 10 * u), torsoBot + 0.04 * HH]], front: false });
514	  else if (mode === "fall") for (const side of [-1, 1]) arms.push({ pts: [sh(side), [tcx + side * (1.15 * T.a + 12 * u), sh(side)[1] - 0.25 * HH], [tcx + side * (1.3 * T.a + 24 * u), sh(side)[1] - 0.68 * HH]], front: false });
515	  else {
516	    arms.push({ pts: prop === "shako" ? hang(-1, 0) : hang(-1, -sw), front: false });
517	    if (rifle) {
518	      const G = lerp2(R0, R1, 0.1);
519	      arms.push({ pts: [sh(1), [tcx + 1.12 * T.a + 5 * u, sh(1)[1] + 0.45 * HH], G], front: false });
520	    } else if (wave !== undefined) {
521	      const S = sh(1);
522	      arms.push({ pts: [S, [tcx + 1.1 * T.a + 10 * u + 3 * u * wave, S[1] - 0.22 * HH], [tcx + 1.18 * T.a + 16 * u + 12 * u * wave, S[1] - 0.6 * HH]], front: false });
523	    } else if (prop === "icecream") {
524	      const S = sh(1);
525	      arms.push({ pts: [S, [tcx + 1.05 * T.a + 4 * u, S[1] + 0.45 * HH], [tcx + 0.5 * T.a, S[1] + 0.4 * HH]], front: true });
526	    } else if (Array.isArray(prop)) {
527	      const S = sh(1), k = clamp(prop[1], 0, 1);
528	      const E = lerp2([tcx + 1.1 * T.a + 10 * u, S[1] - 0.15 * HH], [tcx + 1.2 * T.a + 10 * u, S[1] + 0.3 * HH], k);
529	      const Hd = lerp2([tcx + 1.15 * T.a + 14 * u, S[1] - 0.55 * HH], [tcx + 1.45 * T.a + 22 * u, S[1] + 0.35 * HH], k);
530	      arms.push({ pts: [S, E, Hd], front: true });
531	    } else arms.push({ pts: hang(1, sw), front: false });
532	  }
533	  const drawArm = (a: Arm) => { p.stroke(curve(a.pts[0], a.pts[1], a.pts[2]), 5.2 * u, armCol); p.dot(a.pts[2][0], a.pts[2][1], 5.5 * u); };
534	  // behind the body: rifle, sword, arms
535	  if (rifle) {
536	    p.band([R0, R1], "#7a4b2a", 5 * u, 1.5 * u, "round");
537	    p.band([lerp2(R0, R1, 0.6), R1], "#8d949c", 2.4 * u, 1.2 * u, "round");
538	  }
539	  if (o.sword && mode !== "sit") {
540	    const s0: P2 = [tcx - 0.75 * T.a, torsoBot - 0.2 * HH];
541	    p.band([s0, [s0[0] - Math.sin(rad(25)) * 0.8 * HH, s0[1] + Math.cos(rad(25)) * 0.8 * HH]], "#c9ccd2", 3 * u, 1.2 * u, "round");
542	  }
543	  for (const a of arms) if (!a.front) drawArm(a);
544	  // torso / dress: shaded fill -> clothing clipped to it -> thick-thin ink ring
545	  if (dress) {
546	    const D: Blob = { a: 0.5 * W * 0.98, b: 0.5 * ((sole - 0.35 * HH) - (chin - 0.2 * HH)), nTop: 2.0, nBot: 3.0, egg: 0.35, asym: 0.03 * facing, rot: 0, noise: 0.006, seed: seed + 9 };
547	    const dp = blobPts(300, sole - 0.35 * HH - D.b, D);
548	    p.gradFill(dp, o.dress!, mul(o.dress!, SH_CLOTH), light);
549	    p.inkRing(dp, ow, thick);
550	    const Sw: Blob = { a: 0.37 * W, b: 0.3 * HH, nTop: 2.2, nBot: 2.4, egg: 0.1, asym: 0, rot: 0, noise: 0.006, seed: seed + 8 };
551	    const sp = blobPts(300, chin + 0.12 * HH, Sw);
552	    p.gradFill(sp, o.jacket, mul(o.jacket, SH_CLOTH), light);
553	    p.inkRing(sp, ow * 0.9, thick);
554	  } else {
555	    p.gradFill(tp, o.jacket, mul(o.jacket, SH_CLOTH), light);
556	    p.clip(tp, () => {
557	      if (o.belt) {
558	        for (const s of [-1, 1]) p.band([[tcx - s * 0.75 * T.a, chin - 0.05 * HH], [tcx + s * 0.8 * T.a, torsoBot - 0.1 * HH]], o.belt!, 5.5 * u, 1.8 * u);
559	        const xc = tcx + 0.025 * T.a, yc = chin - 0.05 * HH + (torsoBot - 0.1 * HH - (chin - 0.05 * HH)) * (0.75 / 1.55);
560	        p.poly([[xc - 3.5 * u, yc - 3.5 * u], [xc + 3.5 * u, yc - 3.5 * u], [xc + 3.5 * u, yc + 3.5 * u], [xc - 3.5 * u, yc + 3.5 * u]], "#d9dde0", 1.5 * u);
561	      }
562	      if (o.sash) p.band([[tcx - 1.3 * T.a, torsoBot - 0.32 * HH], [tcx + 1.3 * T.a, torsoBot - 0.32 * HH]], o.sash, 0.13 * HH, 1.8 * u);
563	      for (let i = 0; i < 4; i++) {
564	        const y = chin + 0.12 * HH + i * 0.2 * HH;
565	        if (o.sash && Math.abs(y - (torsoBot - 0.32 * HH)) < 0.08 * HH) continue;
566	        p.dot(tcx + 2 * u * facing, y, 2.2 * u + 0.8 * u, INK); p.dot(tcx + 2 * u * facing, y, 2.2 * u, o.buttons ?? shade(o.jacket, 0.7));
567	      }
568	    });
569	    if (o.sash) { const s = facing || 1; p.poly([[tcx + s * 0.55 * T.a, torsoBot - 0.3 * HH], [tcx + s * 0.75 * T.a, torsoBot + 0.05 * HH], [tcx + s * 0.45 * T.a, torsoBot + 0.02 * HH]], o.sash, 1.6 * u); }
570	    p.inkRing(tp, ow, thick);
571	  }
572	  // in front of the body: hands holding props
573	  for (const a of arms) if (a.front) {
574	    drawArm(a);
575	    const [hx, hy] = a.pts[2];
576	    if (prop === "icecream") {
577	      p.poly([[hx - 8 * u, hy - 12 * u], [hx + 8 * u, hy - 12 * u], [hx, hy + 7 * u]], "#e0a35a", 1.8 * u);
578	      p.ell(hx, hy - 19 * u, 11 * u, 10 * u, "#f7c6d9", 2.2 * u);
579	      p.dot(hx, hy, 5.5 * u);
580	    } else if (Array.isArray(prop)) {
581	      const ang = rad(-70 + 105 * clamp(prop[1], 0, 1));
582	      const Rh = (pts: P2[]) => rotPts(pts, ang, hx, hy);
583	      p.band(Rh([[hx, hy + 12 * u], [hx, hy - 44 * u]]), "#8a5a34", 5 * u, 1.5 * u, "round");
584	      p.poly(Rh([[hx - 12 * u, hy - 58 * u], [hx + 20 * u, hy - 58 * u], [hx + 20 * u, hy - 42 * u], [hx - 12 * u, hy - 42 * u]]), "#7d848c", 2.2 * u);
585	      p.dot(hx, hy, 5.5 * u);
586	    }
587	  }
588	  if (prop === "shako") { // carried by the left hand
589	    const [hx, hy] = arms[0].pts[2];
590	    p.poly([[hx - 14 * u, hy + 3 * u], [hx + 14 * u, hy + 3 * u], [hx + 16 * u, hy + 30 * u], [hx - 16 * u, hy + 30 * u]], "#3a3d47", 2.2 * u);
591	    p.ell(hx, hy + 31 * u, 3.5 * u, 3.5 * u, "#2b7a4b", 1.5 * u);
592	    p.dot(hx, hy, 5.5 * u);
593	  }
594	  // ---- head: rotates with the body, plus its own tilt about the chin ----
595	  const Ah = A + headTilt, [cpx, cpy] = rotAbout([300, chin], rad(A), [300, hipY]);
596	  p.rot = Ah ? [rad(Ah), 300, chin, cpx - 300, cpy - chin] : null;
597	  hatBehind(p, o, H, 300, hc, light, thick, ow, false);
598	  const hp = blobPts(300, hc, H);
599	  p.shadedFill(hp, skin, mul(skin, SH_SKIN), light, H.a);
600	  p.inkRing(hp, ow, thick);
601	  hatOn(p, o, hp, H, 300, hc, light, seed, facing, false);
602	  const brim = !!o.hat && o.hat !== "hair" && o.hat !== "bonnet" && o.hat !== "cap";
603	  faceFront(p, 300, hc, W, expr, facing, look, lid, brim, skin, o.moustache, o.build === "stout");
604	  p.rot = null;
605	};
606	
607	export type SideOpts = {
608	  phase?: number; expr?: Expr; mode?: "march" | "stand" | "swing" | "push"; blink?: boolean | number; stomp?: number; pose?: number;
609	  /** step length as a multiple of 0.8 m (370 units): matches 1.6 m/s at 2 steps/s; scale by the view's foreshortening */
610	  stride?: number; light?: number; seed?: number;
611	  /** push mode: where the hands land at pose 1, in final canvas units (e.g. the swing kid's back) */
612	  hand?: [number, number];
613	};
614	
615	/** two-bone leg, knee bending forward (+x) */
616	const ik = (hip: P2, ank: P2, l1: number, l2: number): P2 => {
617	  const dx = ank[0] - hip[0], dy = ank[1] - hip[1], d = clamp(Math.hypot(dx, dy), 1, l1 + l2 - 0.01);
618	  const A = Math.acos(clamp((l1 * l1 + d * d - l2 * l2) / (2 * l1 * d), -1, 1)), k = Math.atan2(dy, dx) - A;
