const L3 = (a, b, t) => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
const cr = (p0, p1, p2, p3, t) => {
  const t2 = t * t, t3 = t2 * t;
  return [0, 1, 2].map((i) => 0.5 * (2 * p1[i] + (-p0[i] + p2[i]) * t + (2 * p0[i] - 5 * p1[i] + 4 * p2[i] - p3[i]) * t2 + (-p0[i] + 3 * p1[i] - 3 * p2[i] + p3[i]) * t3));
};
export const path = (pts, t) => {
  const n = pts.length - 1, x = clamp(t) * n, i = Math.min(n - 1, Math.floor(x)), u = x - i;
  return cr(pts[Math.max(0, i - 1)], pts[i], pts[i + 1], pts[Math.min(n, i + 2)], u);
};
const EASE = { smooth, out: easeOut, in: easeIn, lin: (t) => clamp(t) };

/** keys: [{f, pos, look, fov, roll, ease, via:[[x,y,z]...]}] — glide from key i to i+1 over their frame span. */
export function camFromKeys(keys, f, opts = {}) {
  let k = 0; while (k < keys.length - 1 && f >= keys[k + 1].f) k++;
  const A = keys[k], B = keys[Math.min(k + 1, keys.length - 1)];
  const t = A === B ? 0 : (EASE[B.ease || 'smooth'])(prog(f, A.f, B.f));
  const pos = B.via ? path([A.pos, ...B.via, B.pos], t) : L3(A.pos, B.pos, t);
  const look = L3(A.look, B.look, t);
  let fov = lerp(A.fov ?? 45, B.fov ?? 45, t), roll = lerp(A.roll ?? 0, B.roll ?? 0, t);
  // impact kicks: sign flips every frame, decays over 7 f
  for (const kk of opts.kicks || []) {
    const d = f - kk.f; if (d < 0 || d >= 7) continue;
    const a = kk.amp * (1 - d / 7) * (d % 2 ? -1 : 1);
    look[1] += a * 0.25; look[0] += a * 0.12; roll += a * 1.8;
  }
  return { pos, look, fov, roll };
}
export function idle(f, seed) {
  return { bob: 0.01 * Math.sin(f * 0.19 + seed * 2.1), tilt: 1.4 * Math.sin(f * 0.11 + seed * 1.7), head: 2.2 * Math.sin(f * 0.07 + seed * 3.3) };
}
/** blink weight 0..1 (4-frame blink every 15-70 f) */
export function blinkAt(f, seed) {
  let t = Math.floor(hash(seed) * 40), i = 0;
  while (t <= f) { if (f < t + 4) return [0.5, 1, 1, 0.5][f - t]; t += 15 + Math.floor(hash(seed * 7.3 + i) * 55); i++; }
  return 0;
}
/** walk: distance travelled and step phase (2 steps/s) */
export function walk(f, f0, speed = 1.3) { const t = Math.max(0, f - f0) / 30; return { d: t * speed, phase: (t * 1.0) % 1 }; }

