const PISA_RED = "#c8302c";
/** pole (+ optional waving Pisan banner) held at the right hand, drawn behind the body */
const drawPole = (p, banner, ph, tipY = 120) => {
  const x = 418, y0 = 960;
  p.band([[x, y0], [x, tipY]], "#7a4b2a", 11, 3, "round");
  if (banner) {
    const pts = [], pts2 = [];
    const W = 210, H = 150, top = tipY + 18;
    for (let i = 0; i <= 12; i++) { const t = i / 12, w = 14 * t * Math.sin(ph * 6.283 + t * 5); pts.push([x + W * t, top + w]); pts2.push([x + W * t, top + H + w * 1.2 + 10 * t]); }
    const flag = [...pts, ...pts2.reverse()];
    p.poly(flag, PISA_RED, 9);
    // white cross (follows the wave)
    const at = (t, v) => { const w = 14 * t * Math.sin(ph * 6.283 + t * 5); return [x + W * t, top + w + v * (H + 10 * t)]; };
    p.poly([at(0.45, 0.18), at(0.57, 0.18), at(0.57, 0.82), at(0.45, 0.82)], "#f6f1e6", 0);
    p.poly([at(0.22, 0.42), at(0.8, 0.42), at(0.8, 0.58), at(0.22, 0.58)], "#f6f1e6", 0);
  } else {
    p.poly([[x - 16, tipY + 40], [x, tipY - 30], [x + 16, tipY + 40]], "#c9ccd2", 7); // spear head
  }
};

/** a = {outfit, mode, phase, expr, blink, prop, tilt, headTilt, wave, facing, look, seed, extra, bannerPhase} */
export function drawActor(canvas, a) {
  const g = canvas.getContext("2d");
  g.setTransform(1, 0, 0, 1, 0, 0); g.clearRect(0, 0, canvas.width, canvas.height);
  g.setTransform(canvas.width / 600, 0, 0, canvas.height / 1000, 0, 0);
  const p = new Pen(g);
  const o = OUTFITS[a.outfit];
  if (a.extra === "spear" || a.extra === "banner") drawPole(p, a.extra === "banner", a.bannerPhase || 0, a.poleTip ?? 120);
  bodyFront(p, o, { phase: a.phase || 0, expr: a.expr || "neutral", mode: a.mode || "stand", blink: a.blink || 0, prop: a.prop ?? null,
    tilt: a.tilt || 0, headTilt: a.headTilt || 0, wave: a.wave, facing: a.facing || 0, look: a.look || 0, seed: a.seed || 1, lift: 60 });
}

