/** sprite canvases are 300 x 300 design units unless noted */
export function drawSprite(canvas, name, t = 0) {
  const g = canvas.getContext("2d");
  g.setTransform(1, 0, 0, 1, 0, 0); g.clearRect(0, 0, canvas.width, canvas.height);
  g.setTransform(canvas.width / 300, 0, 0, canvas.height / 300, 0, 0);
  const p = new Pen(g); p.ol = 7;
  switch (name) {
    case "pigeon0": pigeon(p, true, false); break;
    case "pigeon1": pigeon(p, false, false); break;
    case "chick0": pigeon(p, true, true); break;
    case "chick1": pigeon(p, false, true); break;
    case "fly0": pigeonFly(p, true); break;
    case "fly1": pigeonFly(p, false); break;
    case "nest": nest(p); break;
    case "leafA": leaf(p, "#e2862e"); break;
    case "leafB": leaf(p, "#c9442c"); break;
    case "drop": drop(p); break;
    case "snow": snow(p); break;
    case "hammer": hammerSprite(p); break;
    case "block": block(p); break;
    case "flag": flag(p, t); break;
    case "puff": g.setTransform(canvas.width / 300, 0, 0, canvas.height / 300, 0, 0); fxPuff(p, t); break;
    case "creak": fxCreak(p, t); break;
    case "laugh": laughMarks(p, t); break;
    case "cloud": g.setTransform(canvas.width / 600, 0, 0, canvas.height / 300, 0, 0); fxCloud(p, Math.round(t)); break;
  }
}

