const KICKS = [{ f: 166, amp: 1.0 }, { f: 669, amp: 1.6 }, { f: 688, amp: 0.7 }];
export function camAt(f) {
  const s = shotAt(f);
  if (s.id === 5) {
    const t = smooth(prog(f, 368, 444)) * 0.85 + prog(f, 368, 444) * 0.15, a = (18 + 82 * t) * Math.PI / 180, r = 24 - 2 * t;
    return { pos: [r * Math.sin(a), 3.2 + 1.2 * t, r * Math.cos(a)], look: [0.8, 6.4, 0], fov: 42, roll: 2 * Math.sin(t * 3) };
  }
  return camFromKeys(CAMS[s.id], f, { kicks: KICKS });
}
// DOF: focus distance (m) + cInf px at 1080 wide (0 = sharp)
export function dofAt(f) {
  const s = shotAt(f).id;
  if (s === 2) return { focus: 6.2, cInf: 11 };
  if (s === 6) return f < 492 ? { focus: 8.6, cInf: 12 } : { focus: lerp(8.6, 7.4, prog(f, 492, 516)), cInf: lerp(12, 9, prog(f, 492, 516)) };
  if (s === 4) return { focus: 9, cInf: 6 };
  if (s === 1 && f < 30) return { focus: 9.8, cInf: 8 * (1 - prog(f, 10, 30)) };
  return { focus: 20, cInf: 0 };
}
export const shadowCenter = (f) => { const s = shotAt(f).id; return s === 2 || s === 4 ? [-5, 0, 0] : s === 6 && f > 500 ? [-2, 0, 6] : s === 8 ? [8, 0, 0] : [0, 0, 2]; };

// ---- world state ----
const seasonCol = (t) => { // t in 0..2 (two cycles): green -> gold -> snow -> green
  const u = (t % 1) * 4; // 0 spring,1 summer->autumn,2 autumn,3 winter
  const G = [0.44, 0.68, 0.27], A = [0.80, 0.62, 0.25], W = [0.93, 0.95, 0.98];
  const L = (a, b, k) => a.map((v, i) => lerp(v, b[i], k));
  const k = u < 1 ? [G, G, 0] : u < 2 ? [G, A, u - 1] : u < 3 ? [A, W, u - 2] : [W, G, u - 3];
  return { grass: L(k[0], k[1], smooth(k[2])), snow: u < 2 ? 0 : u < 3 ? smooth(u - 2) : 1 - smooth(u - 3), autumn: u > 1 && u < 2.6 ? 1 : 0, winter: u > 2.2 && u < 3.4 ? 1 : 0 };
};
export function worldAt(f) {
  const s = shotAt(f).id;
  const w = { floors: 3, grow: 1, tilt: 3.2, dy: 0, scaffold: false, ivy: 0, front: 0, frontHidden: false, clay: 1, clayWet: 0, clayDark: 0,
    ghost: null, season: null, flag: false, finished: false, crowdDust: 0, pigeons: 0 };
  if (s === 1 || s === 9) { w.floors = 8; w.tilt = 5.2; w.finished = true; w.flag = true; }
  if (s === 2) {
    w.scaffold = true;
    const t = prog(f, 158, 176); w.tilt = 3.2 * back(t, 2.4) + 0.12 * Math.sin(Math.max(0, f - 176) * 0.6) * Math.exp(-Math.max(0, f - 176) * 0.15);
  }
  if (s === 3) {
    w.scaffold = true; w.front = easeIn(prog(f, 189, 206)); w.frontHidden = f > 206;
    const p = pulse(f, 213, 12) * 0.6 + pulse(f, 229, 10) * 0.5 + pulse(f, 258, 18) * 1.2;
    w.clay = 1 - 0.07 * p; w.dy = -6.8 * 0.07 * p; w.clayWet = 1;
  }
  if (s === 4) { w.scaffold = true; }
  if (s === 5) { w.ivy = 0.25 + 0.75 * prog(f, 370, 444); w.season = seasonCol(prog(f, 370, 444) * 2); }
  if (s === 6) { w.ivy = 1; w.pigeons = 1; }
  if (s === 7) {
    w.frontHidden = true; w.ivy = 1; const t = smooth(prog(f, 556, 622));
    w.clay = 1 - 0.18 * t; w.dy = -6.8 * 0.18 * t; w.clayDark = t; w.clayWet = 1 - 0.7 * t;
  }
