const saved = [];
function swapForNd(on) {
  if (on) {
    saved.length = 0;
    scene.traverse((o) => {
      if (!o.isMesh) return;
      const nd = o.userData.nd || 'world';
      saved.push([o, o.material, o.visible]);
      if (nd === 'hide') o.visible = false;
      else if (nd === 'card') o.material = o.userData.ndMat;
      else o.material = o.material === M.ivy ? ivyND : ndWorld;
    });
    scene.fog_ = scene.fog; scene.fog = null;
  } else {
    for (const [o, m, v] of saved) { o.material = m; o.visible = v; }
    scene.fog = scene.fog_;
  }
}

