"""audio.py -> audio/music.wav + audio/sfx.wav (48 kHz mono stems, exact voice length). Synths stay; cue table is per story."""
import numpy as np, wave, json
SR = 48000
dur = json.load(open('work/phrases.json'))['duration']; N = int(round(dur * SR))
rng = np.random.default_rng(7)
F = lambda f: int(f / 30 * SR)

def env(n, a=0.005, r=0.2):
    t = np.arange(n) / SR
    return np.minimum(1, t / max(a, 1e-4)) * np.exp(-t / max(r, 1e-4))

def place(buf, x, at):
    a = max(0, at); b = min(len(buf), at + len(x))
    if b > a: buf[a:b] += x[a - at:b - at]

def lpf(x, fc):
    X = np.fft.rfft(x); fr = np.fft.rfftfreq(len(x), 1 / SR); X *= 1 / (1 + (fr / fc) ** 4); return np.fft.irfft(X, len(x))

def hpf(x, fc):
    X = np.fft.rfft(x); fr = np.fft.rfftfreq(len(x), 1 / SR); X *= 1 / (1 + (fc / np.maximum(fr, 1)) ** 4); return np.fft.irfft(X, len(x))

def tone(freq, n, kind='sine'):
    ph = 2 * np.pi * np.cumsum(np.broadcast_to(freq, (n,))) / SR
    if kind == 'saw': return 2 * ((ph / (2 * np.pi)) % 1) - 1
    if kind == 'sq': return np.sign(np.sin(ph))
    return np.sin(ph)

def noise(n): return rng.standard_normal(n)

# ---------------- instruments ----------------
def kick():
    n = int(0.35 * SR); t = np.arange(n) / SR
    return np.sin(2 * np.pi * np.cumsum(50 + 110 * np.exp(-t * 30)) / SR) * env(n, 0.002, 0.12)
def snare():
    n = int(0.25 * SR); return (hpf(noise(n), 1500) * 0.6 + tone(190, n) * 0.4) * env(n, 0.001, 0.07)
def pluck(f, d=0.4):
    n = int(d * SR); return (tone(f, n, 'saw') * 0.5 + tone(f * 2, n) * 0.3) * env(n, 0.003, 0.12)
def brass(f, d):
    n = int(d * SR); t = np.arange(n) / SR; vib = 1 + 0.004 * np.sin(2 * np.pi * 5.5 * t)
    x = tone(f * vib, n, 'saw') * 0.6 + tone(f * 2 * vib, n, 'saw') * 0.2
    e = np.minimum(1, t / 0.06) * np.clip((d - t) / 0.08, 0, 1); return lpf(x * e, 2200)
def fife(f, d):
    n = int(d * SR); t = np.arange(n) / SR
    x = tone(f * (1 + 0.006 * np.sin(2 * np.pi * 6 * t)), n) + 0.02 * noise(n)
    return x * np.minimum(1, t / 0.02) * np.clip((d - t) / 0.05, 0, 1)

# ---------------- music: medieval-ish march loop, stops at the twist (f688) ----------------
music = np.zeros(N)
BPM = 112; beat = 60 / BPM; stop = F(688)
key = {'D': 146.83, 'A': 110.0, 'G': 98.0, 'F': 87.31, 'C': 130.81}
prog = ['D', 'D', 'C', 'A', 'D', 'F', 'G', 'A']
mel = [587.3, 659.3, 698.5, 659.3, 587.3, 523.3, 587.3, 440.0, 587.3, 659.3, 698.5, 784.0, 880.0, 784.0, 698.5, 659.3]
b = 0
while True:
    at = int(b * beat * SR)
    if at >= stop: break
    bar = b // 4; ch = key[prog[bar % 8]]
    golden = F(287) <= at < F(368); night = F(539) <= at < F(634); whatif = F(634) <= at < F(688)
    lvl = 0.6 if night else 1.0
    if b % 2 == 0: place(music, kick() * 0.9 * lvl, at)
    if b % 2 == 1 and not night: place(music, snare() * 0.45, at)
    if b % 4 == 3 and not night: place(music, snare() * 0.25, at + int(beat * SR / 2))
    place(music, pluck(ch / 2 if b % 2 else ch, beat * 0.9) * 0.35 * lvl, at)
    if b % 4 == 0: place(music, brass(ch, beat * 3.8) * (0.32 if golden else 0.22) * lvl, at)
    if not night and not whatif and (bar % 4) in (1, 3): place(music, fife(mel[b % 16], beat * 0.85) * 0.12, at)
    if whatif: place(music, fife(mel[(b * 3) % 16] * 0.5, beat * 0.4) * 0.08, at)
    b += 1
fade = np.ones(N); fl = int(0.05 * SR); fade[stop - fl:stop] = np.linspace(1, 0, fl); fade[stop:] = 0; music *= fade
dn = N - stop; t = np.arange(dn) / SR
drone = (tone(73.4, dn, 'saw') * 0.5 + tone(110, dn, 'saw') * 0.3 + tone(146.8, dn) * 0.3) * np.minimum(1, t / 0.3) * np.clip((dn / SR - t) / 0.6, 0, 1)
place(music, lpf(drone, 900) * 0.5, stop)

# ---------------- SFX ----------------
sfx = np.zeros(N)
def whoosh(d=0.6, up=True):
    n = int(d * SR); t = np.arange(n) / SR; x = noise(n); e = np.sin(np.pi * t / d) ** 2
    return (lpf(x, 900 if up else 600) * 0.7 + hpf(x, 300) * 0.3) * e * 0.5
def thunk(f0=90):
    n = int(0.3 * SR); t = np.arange(n) / SR
    return (np.sin(2 * np.pi * np.cumsum(f0 + 60 * np.exp(-t * 40)) / SR) + 0.3 * lpf(noise(n), 800)) * env(n, 0.001, 0.08)
def tink(f=2400):
    n = int(0.25 * SR); return (tone(f, n) + 0.5 * tone(f * 2.7, n)) * env(n, 0.001, 0.05) * 0.5
def creak(d=0.8, f0=140):
    n = int(d * SR); t = np.arange(n) / SR; fr = f0 * (1 + 0.25 * np.sin(2 * np.pi * 1.3 * t)); x = tone(fr, n, 'saw')
    pulses = (np.sin(2 * np.pi * 34 * t) > 0.6).astype(float); return lpf(x * (0.4 + 0.6 * pulses), 1600) * np.sin(np.pi * t / d) * 0.6
def rumble(d=1.5):
    n = int(d * SR); t = np.arange(n) / SR; return lpf(noise(n), 120) * 3 * np.minimum(1, t / 0.05) * np.exp(-t / (d / 3))
def crash(d=1.2):
    n = int(d * SR); t = np.arange(n) / SR; return (hpf(noise(n), 400) * 0.6 + lpf(noise(n), 300) * 1.5) * np.exp(-t / 0.25)
def squelch(d=0.35):
    n = int(d * SR); t = np.arange(n) / SR; fr = 300 * np.exp(-t * 6) + 80
    return (tone(fr, n) * 0.6 + lpf(noise(n), 500) * 0.6) * np.sin(np.pi * t / d) ** 0.5
def drip():
    n = int(0.18 * SR); t = np.arange(n) / SR; return tone(900 + 1400 * t / 0.18, n) * env(n, 0.001, 0.04) * 0.5
def coo():
    n = int(0.45 * SR); t = np.arange(n) / SR; fr = 420 + 60 * np.sin(2 * np.pi * 3 * t)
    return lpf(tone(fr, n) * (0.6 + 0.4 * np.sin(2 * np.pi * 18 * t)), 1200) * np.sin(np.pi * t / 0.45) * 0.5
def pop():
    n = int(0.08 * SR); t = np.arange(n) / SR; return tone(600 + 900 * t / 0.08, n) * env(n, 0.001, 0.02)
def flap():
    n = int(0.3 * SR); t = np.arange(n) / SR; return hpf(noise(n), 900) * (np.sin(2 * np.pi * 9 * t) > 0) * np.sin(np.pi * t / 0.3) * 0.4
def step():
    n = int(0.09 * SR); return lpf(noise(n), 700) * env(n, 0.002, 0.03)
def sting():
    n = int(2.0 * SR); t = np.arange(n) / SR
    return (np.sin(2 * np.pi * np.cumsum(45 + 40 * np.exp(-t * 8)) / SR) * 1.2 + lpf(noise(n), 200)) * np.exp(-t / 0.7)
def ting():
    n = int(1.2 * SR); return (tone(1568, n) + 0.6 * tone(2349, n) + 0.3 * tone(3136, n)) * env(n, 0.002, 0.35) * 0.4
def laugh():
    out = np.zeros(int(0.7 * SR)); n = int(0.08 * SR)
    for k in range(6): place(out, tone(520 - k * 25, n, 'sq') * env(n, 0.005, 0.04) * 0.25, int(k * 0.11 * SR))
    return lpf(out, 2500)
def wind(d):
    n = int(d * SR); t = np.arange(n) / SR; return lpf(noise(n), 500) * (0.6 + 0.4 * np.sin(2 * np.pi * 0.6 * t)) * np.sin(np.pi * t / d) * 0.6

cues = []
def cue(f, x, g=1.0, name=''):
    place(sfx, x * g, F(f)); cues.append((f, name))
# S1 hook
cue(4, whoosh(1.4), 0.8, 'crane whoosh')
for k in range(6): cue(30 + 10 * k, step(), 0.4, 'march step')
cue(66, flap(), 0.8, 'banner flap'); cue(70, thunk(110), 0.5, 'spear stamp')
# S2 worksite
cue(92, whoosh(0.5), 0.6, 'flash whoosh')
for f in range(96, 166, 14): cue(f + 10, tink(2600), 0.5, 'hammer tink')
cue(156, creak(1.0, 120), 0.9, 'tip creak'); cue(165, thunk(70), 0.9, 'tip thunk'); cue(166, rumble(1.0), 0.5, 'groan')
# S3 cutaway
cue(189, whoosh(0.7, False), 0.8, 'ground drops'); cue(205, thunk(60), 0.6, 'ground lands')
for f, gn in [(213, 0.6), (229, 0.55), (258, 0.9)]: cue(f, squelch(0.4 if f < 250 else 0.6), gn, 'squelch')
for f in [216, 233, 262, 270]: cue(f, drip(), 0.5, 'drip')
# S4 builders leave
cue(296, brass(293.7, 0.35) * 0.5 + brass(440, 0.35) * 0.3, 0.9, 'trumpet blat')
for f in range(304, 366, 8): cue(f, step(), 0.35, 'footstep')
cue(321, tink(1800) + np.pad(thunk(150) * 0.5, (0, 0))[:int(0.25 * SR)], 0.7, 'hammer drop'); cue(329, thunk(120), 0.6, 'block drop')
# S5 seasons
cue(368, whoosh(0.5), 0.6, 'flash whoosh'); cue(372, wind(2.4), 0.6, 'wind'); cue(405, wind(1.8), 0.5, 'wind 2')
# S6 pigeons + locals
for f in [447, 457, 467, 477]:
    cue(f, pop(), 0.6, 'pop'); cue(f + 2, coo(), 0.6, 'coo')
cue(492, whoosh(0.9, False), 0.6, 'crane down'); cue(517, laugh(), 0.9, 'laugh')
# S7 explanation
cue(556, creak(2.0, 70) * 0.6 + rumble(2.0) * 0.5, 0.8, 'squeeze')
for k in range(6): cue(565 + 9 * k, drip(), 0.45, 'drip')
# S8 ghost
cue(636, whoosh(0.7), 0.7, 'grow whoosh')
for k in range(4): cue(640 + 4 * k, pop(), 0.3, 'stack')
cue(656, creak(0.5, 90), 0.7, 'lean creak'); cue(662, whoosh(0.3, False), 0.6, 'fall'); cue(668, crash(1.6) + rumble(1.6), 0.9, 'crash')
# S9 sting + payoff
cue(688, sting(), 1.0, 'sting')
for k in range(3): cue(700 + 12 * k, flap(), 0.5, 'wings')
cue(745, ting(), 0.9, 'ting on stands')

def wr(name, x):
    w = wave.open(name, 'wb'); w.setnchannels(1); w.setsampwidth(2); w.setframerate(SR)
    w.writeframes((np.clip(x / max(1e-9, np.abs(x).max()) * 0.9, -1, 1) * 32767).astype(np.int16).tobytes()); w.close()
wr('audio/music.wav', music); wr('audio/sfx.wav', sfx)
open('audio/cues.md', 'w').write('\n'.join(f'- f{f} ({f/30:.2f}s) {n}' for f, n in cues))
print('stems written', round(dur, 3), 's', len(cues), 'cues')
